/* Scripture Launchpad — 2 Corinthians, Galatians, Ephesians, Philippians, Colossians */
window.SLP = window.SLP || { books: [], gloss: [] }; var SLP = window.SLP;
var _co2 = SLP.books.find(function(b){ return b.id === "2-cor"; });
if (!_co2) throw new Error("data/canon.js must load before nt-06-2cor-col.js");
(_co2.chapters = _co2.chapters || []).push(
  { n:1, summary:"Paul greets the church at Corinth and the saints of all Achaia in the name of himself and Timothy, then blesses God as the Father of mercies and the God of all comfort. His argument: God comforts believers in every tribulation so that they in turn can comfort others who are in any trouble. Paul's own trouble in Asia pressed him beyond strength until he despaired of life; that experience taught him to trust not in himself but in the God who raises the dead, and the prayers of many helped deliver him. He then answers a criticism that he wavers in his plans: his word to them was as dependable as God's promises, which are all yes in Christ, who has sealed believers and given the Spirit as an earnest in their hearts. He postponed his visit to spare them, for he and his companions are helpers of their joy, not masters over their faith.",
    context:"Paul writes this follow-up letter to the church at Corinth after a painful visit and a severe letter, defending his ministry against critics in Achaia.",
    keyVerses:[
      { ref:"2 Corinthians 1:3", text:"Blessed be God, even the Father of our Lord Jesus Christ, the Father of mercies, and the God of all comfort;" },
      { ref:"2 Corinthians 1:4", text:"Who comforteth us in all our tribulation, that we may be able to comfort them which are in any trouble, by the comfort wherewith we ourselves are comforted of God." },
      { ref:"2 Corinthians 1:9", text:"But we had the sentence of death in ourselves, that we should not trust in ourselves, but in God which raiseth the dead:" }
    ],
    takeaway:"God comforts us in every tribulation so that we can pass that comfort to others.",
    quiz:[
      { q:"Who joins Paul in greeting the church at Corinth at the start of 2 Corinthians?", choices:["Silas","Timothy our brother","Titus","Luke"], a:1, why:"Verse 1 addresses the church of God which is at Corinth from Paul and Timothy our brother." },
      { q:"Why does Paul say God comforts believers in tribulation?", choices:["So they can comfort others who are in any trouble","So they will never suffer again","So they can avoid all sorrow","So others will envy their peace"], a:0, why:"Verse 4 says God comforteth us in all our tribulation, that we may be able to comfort them which are in any trouble." },
      { q:"What did Paul's despairing trouble in Asia teach him?", choices:["To plan travel more carefully","To rely on his own endurance","To avoid hostile cities","Not to trust in himself but in God which raiseth the dead"], a:3, why:"Verse 9 says they had the sentence of death in themselves, that they should not trust in themselves, but in God which raiseth the dead." }
    ] },
  { n:2, summary:"Paul explains why he avoided another painful visit and instead wrote through tears: he wanted them to feel the love behind the severe letter. The man the congregation punished has suffered enough, so Paul urges them to forgive, comfort, and confirm their love toward him, lest excessive sorrow swallow him and Satan gain an advantage through unforgiveness; Paul forgave the man for their sakes, in the person of Christ, as a test of their obedience. He then recalls a restless journey: although a door for preaching opened at Troas, he could not rest without news from Titus and moved on to Macedonia. The chapter turns to triumph: God always leads His servants in triumph, making them a sweet savour of Christ everywhere, the smell of death to those perishing and of life to those being saved, and Paul speaks the word sincerely, not corrupting it for gain.",
    context:"Paul applies the forgiveness of a disciplined offender and describes a restless journey to Macedonia in search of Titus.",
    keyVerses:[
      { ref:"2 Corinthians 2:7", text:"So that contrariwise ye ought rather to forgive him, and comfort him, lest perhaps such a one should be swallowed up with overmuch sorrow." },
      { ref:"2 Corinthians 2:11", text:"Lest Satan should get an advantage of us: for we are not ignorant of his devices." },
      { ref:"2 Corinthians 2:14", text:"Now thanks be unto God, which always causeth us to triumph in Christ, and maketh manifest the savour of his knowledge by us in every place." }
    ],
    takeaway:"Forgive and comfort the repentant; unchecked sorrow gives Satan an advantage.",
    quiz:[
      { q:"Why did Paul have no rest in his spirit at Troas?", choices:["He had not found Titus there","The city refused to hear him","He was imprisoned there","A storm closed the harbor"], a:0, why:"Verses 12-13 say a door was opened at Troas, but Paul had no rest because he found not Titus his brother, so he went into Macedonia." },
      { q:"Why does Paul urge the Corinthians to forgive and comfort the disciplined offender?", choices:["Because the man was innocent all along","Because punishment is always wrong","Lest he be swallowed up with overmuch sorrow and Satan gain an advantage","Because Roman law required forgiveness"], a:2, why:"Verses 7-11 warn that overmuch sorrow could swallow the man and that Satan should get no advantage, for we are not ignorant of his devices." },
      { q:"What principle should guide a congregation after discipline has done its work?", choices:["Continue punishing to be safe","Confirm your love toward the repentant person","Expel anyone who ever failed","Leave reconciliation to the courts"], a:1, why:"Verse 8 says, I beseech you that ye would confirm your love toward him." }
    ] },
  { n:3, summary:"Paul refuses the games of self-recommendation: the Corinthian believers themselves are his letter of credentials, written not with ink but by the Spirit of the living God, not on tables of stone but on hearts. His sufficiency for such work comes from God, who made him a minister of a new covenant, not of the letter, which kills, but of the Spirit, which gives life. Then the comparison: if the ministry that brought death, engraved on stones, arrived with glory so bright Moses' face had to be veiled, the ministry of the Spirit must be far more glorious, for it remains rather than fades. Because of that hope Paul speaks plainly, without a veil; the same veil hides the old covenant from its readers until they turn to the Lord, who is that Spirit. Where the Spirit of the Lord is there is liberty, and beholding Christ's glory as in a mirror, believers are changed into His image from glory to glory.",
    context:"Paul contrasts the old covenant engraved in stone with the new covenant of the Spirit, which brings surpassing and lasting glory.",
    keyVerses:[
      { ref:"2 Corinthians 3:3", text:"Forasmuch as ye are manifestly declared to be the epistle of Christ ministered by us, written not with ink, but with the Spirit of the living God; not in tables of stone, but in fleshy tables of the heart." },
      { ref:"2 Corinthians 3:6", text:"Who also hath made us able ministers of the new testament; not of the letter, but of the spirit: for the letter killeth, but the spirit giveth life." },
      { ref:"2 Corinthians 3:17", text:"Now the Lord is that Spirit: and where the Spirit of the Lord is, there is liberty." }
    ],
    takeaway:"The new covenant, written on hearts by the Spirit, brings greater glory and liberty than the letter engraved in stone.",
    quiz:[
      { q:"According to Paul, what serves as his letter of recommendation to others?", choices:["A signed certificate from Jerusalem","Miraculous signs of healing","The Corinthian believers themselves","Copies of his sermons"], a:2, why:"Verses 2-3 say ye are our epistle, the epistle of Christ ministered by us, written with the Spirit of the living God on fleshy tables of the heart." },
      { q:"How does Paul argue that the ministration of the Spirit exceeds the ministration of death?", choices:["It has stricter commandments","It came with louder thunder","It lasted longer","If the engraven-on-stones ministry was glorious, much more that which remaineth is glorious"], a:3, why:"Verses 7-11 reason from the fading glory on Moses' face: if that which is done away was glorious, much more that which remaineth is glorious." },
      { q:"What does Paul say the Spirit of the Lord brings where He is?", choices:["Liberty","Silence","Prosperity","Judgment"], a:0, why:"Verse 17 says where the Spirit of the Lord is, there is liberty; beholding Christ's glory, believers are changed into the same image." }
    ] },
  { n:4, summary:"Because God has given him this ministry, Paul does not faint. He has renounced dishonesty and crafty handling of the word, commending himself to every man's conscience; where the gospel is hidden, the god of this world has blinded unbelieving minds. The message is not about the messengers: we preach not ourselves, but Christ Jesus the Lord, with ourselves as servants. God, who once commanded light to shine out of darkness, has shined in our hearts to give the knowledge of His glory in the face of Jesus Christ. Paul carries that treasure in earthen vessels, so that the excellence of the power is plainly God's: pressed on every side yet not crushed, perplexed but not despairing, persecuted but not forsaken, carrying the dying of Jesus so that His life shows in mortal flesh. The outward man perishes, but the inward man is renewed day by day, for momentary affliction works an eternal weight of glory, and the faithful look at unseen, eternal things.",
    context:"Paul describes treasure in earthen vessels and the hope of eternal glory that outweighs present affliction.",
    keyVerses:[
      { ref:"2 Corinthians 4:5", text:"For we preach not ourselves, but Christ Jesus the Lord; and ourselves your servants for Jesus' sake." },
      { ref:"2 Corinthians 4:7", text:"But we have this treasure in earthen vessels, that the excellency of the power may be of God, and not of us." },
      { ref:"2 Corinthians 4:18", text:"While we look not at the things which are seen, but at the things which are not seen: for the things which are seen are temporal; but the things which are not seen are eternal." }
    ],
    takeaway:"God puts glorious treasure in weak vessels so the power is unmistakably His.",
    quiz:[
      { q:"Whom does Paul blame for blinding the minds of those who do not believe?", choices:["The Roman government","The scribes at Jerusalem","The Corinthian critics","The god of this world"], a:3, why:"Verse 4 says the god of this world hath blinded the minds of them which believe not, lest the light of the glorious gospel should shine unto them." },
      { q:"Why does Paul say we have this treasure in earthen vessels?", choices:["To keep the treasure hidden","That the excellency of the power may be of God, and not of us","Because clay preserves manuscripts","To make the gospel expensive"], a:1, why:"Verse 7 explains that the treasure is in earthen vessels so the excellency of the power may be of God and not of us." },
      { q:"What should believers look at when affliction feels heavy, according to this chapter?", choices:["Their reputation","Their suffering","The unseen, eternal things","Their enemies"], a:2, why:"Verses 17-18 call affliction light and momentary against an eternal weight of glory, while we look not at the things which are seen, which are temporal." }
    ] },
  { n:5, summary:"Paul pictures the mortal body as an earthly tent: if it dissolves, the believer has a building of God, eternal in the heavens. In this tent we groan, longing to be clothed with our heavenly dwelling so that mortality is swallowed up of life, and God has given the Spirit as an earnest of it. So Paul is confident, walking by faith and not by sight, willing to be absent from the body and present with the Lord, labouring to be accepted of Him, for all must appear before the judgment seat of Christ. The love of Christ constrains his preaching: one died for all, so those who live should no longer live for themselves. Anyone in Christ is a new creature, old things passed away; God reconciled the world to Himself in Christ, not counting their trespasses, and entrusted to believers the word of reconciliation. We are ambassadors for Christ: be reconciled to God, for He made Him who knew no sin to be sin for us, that in Him we might become the righteousness of God.",
    context:"Paul speaks of the heavenly dwelling that replaces the mortal body and of the ministry of reconciliation committed to believers.",
    keyVerses:[
      { ref:"2 Corinthians 5:7", text:"(For we walk by faith, not by sight:)" },
      { ref:"2 Corinthians 5:17", text:"Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new." },
      { ref:"2 Corinthians 5:20", text:"Now then we are ambassadors for Christ, as though God did beseech you by us: we pray you in Christ's stead, be ye reconciled to God." }
    ],
    takeaway:"Christ's love makes us new creatures and ambassadors of reconciliation to God.",
    quiz:[
      { q:"Before whom must all appear to receive the things done in the body, good or bad?", choices:["The judgment seat of Christ","The council at Corinth","The Jerusalem synagogue","Caesar's tribunal"], a:0, why:"Verse 10 says we must all appear before the judgment seat of Christ, to receive the things done in his body, whether good or bad." },
      { q:"What motivates Paul's persuasion of men, according to verse 14?", choices:["Fear of Roman courts","Hope of donations","Desire for fame","The love of Christ, because one died for all"], a:3, why:"Verse 14 says the love of Christ constraineth us, because if one died for all, then were all dead." },
      { q:"What does it mean that Christians are ambassadors for Christ?", choices:["They hold Roman citizenship","They speak in Christ's stead, urging people to be reconciled to God","They collect taxes for the church","They should avoid unbelieving governments"], a:1, why:"Verse 20 says we are ambassadors for Christ, praying men in Christ's stead: be ye reconciled to God." }
    ] },
  { n:6, summary:"As workers together with Christ, Paul begs them not to receive God's grace in vain: now is the accepted time, now the day of salvation. He catalogs how God's ministers approve themselves, in patience amid afflictions, stripes, imprisonments, tumults, labours, and fastings; in pureness, knowledge, longsuffering, kindness, the Holy Ghost, and love unfeigned; in honour and dishonour, evil report and good report; sorrowful yet always rejoicing, poor yet making many rich, having nothing yet possessing all things. His mouth is open and his heart enlarged toward them, and he asks for their hearts in return. Then a warning: be not unequally yoked with unbelievers, for what concord has Christ with Belial, what agreement the temple of God with idols? Believers are the temple of the living God, who promises to dwell in them; therefore come out from among them and be separate, and God will receive them as sons and daughters.",
    context:"Paul urges the Corinthians not to receive God's grace in vain and lists how true ministers approve themselves amid hardship.",
    keyVerses:[
      { ref:"2 Corinthians 6:2", text:"(For he saith, I have heard thee in a time accepted, and in the day of salvation have I succoured thee: behold, now is the accepted time; behold, now is the day of salvation.)" },
      { ref:"2 Corinthians 6:14", text:"Be ye not unequally yoked together with unbelievers: for what fellowship hath righteousness with unrighteousness? and what communion hath light with darkness?" },
      { ref:"2 Corinthians 6:16", text:"And what agreement hath the temple of God with idols? for ye are the temple of the living God; as God hath said, I will dwell in them, and walk in them; and I will be their God, and they shall be my people." }
    ],
    takeaway:"Because we are the temple of the living God, we live distinctly and do not bind ourselves to unbelief.",
    quiz:[
      { q:"What time does Paul declare in chapter 6?", choices:["The hour of temptation","The year of jubilee","Now is the day of salvation","The sabbath of rest"], a:2, why:"Verse 2 quotes Isaiah: behold, now is the accepted time; behold, now is the day of salvation." },
      { q:"Why should believers not be unequally yoked with unbelievers?", choices:["Because believers are the temple of the living God, and light has no communion with darkness","Because unbelievers are always hostile","Because temple worship required it","Because Paul banned all friendships"], a:0, why:"Verses 14-16 ask what fellowship righteousness has with unrighteousness and declare ye are the temple of the living God." },
      { q:"What promise follows the call to come out from among them and be separate?", choices:["Immediate prosperity","Freedom from persecution","New apostles to lead them","God will receive them and be a Father, and they shall be His sons and daughters"], a:3, why:"Verses 17-18 promise that in separating, I will receive you, and will be a Father unto you, saith the Lord Almighty." }
    ] },
  { n:7, summary:"Paul asserts his integrity: he has wronged, corrupted, and defrauded no one, and the Corinthians live in his heart, to die and live with them. In Macedonia he found fightings without and fears within, but God, who comforts those cast down, comforted him through the coming of Titus and the news of their earnest desire, mourning, and fervent care for him. His severe letter had made them sorry, and he does not regret it, because their sorrow led somewhere: godly sorrow works repentance to salvation, while the sorrow of the world works death. Their grief produced carefulness, clearing of themselves, indignation, fear, and zeal, proving them clear in the matter; Paul wrote less for the offender's sake than to show his care for them in the sight of God. Titus, too, came back refreshed by their obedience, and Paul closes rejoicing in his confidence in them in all things.",
    context:"Paul recounts how Titus brought news of the Corinthians' repentance, turning his anxiety into comfort and joy.",
    keyVerses:[
      { ref:"2 Corinthians 7:6", text:"Nevertheless God, that comforteth those that are cast down, comforted us by the coming of Titus;" },
      { ref:"2 Corinthians 7:9", text:"Now I rejoice, not that ye were made sorry, but that ye sorrowed to repentance: for ye were made sorry after a godly manner, that ye might receive damage by us in nothing." },
      { ref:"2 Corinthians 7:10", text:"For godly sorrow worketh repentance to salvation not to be repented of: but the sorrow of the world worketh death." }
    ],
    takeaway:"Godly sorrow leads to repentance and salvation; worldly sorrow only destroys.",
    quiz:[
      { q:"By whose coming was Paul comforted in Macedonia?", choices:["Silas's","Titus's","Peter's","Apollos's"], a:1, why:"Verse 6 says God, that comforteth those that are cast down, comforted us by the coming of Titus." },
      { q:"What distinction does Paul draw between kinds of sorrow?", choices:["Public sorrow is better than private sorrow","Long sorrow is better than short sorrow","Quiet sorrow is better than loud sorrow","Godly sorrow works repentance to salvation, but the sorrow of the world works death"], a:3, why:"Verse 10 contrasts godly sorrow, which works repentance not to be repented of, with the sorrow of the world, which worketh death." },
      { q:"How should Paul's joy at their godly sorrow shape our view of hard correction?", choices:["Correction that produces repentance is worth the temporary grief it causes","Grief is always a sign of failure","Letters should never confront sin","Repentance matters only for leaders"], a:0, why:"Verses 8-9 show Paul did not regret making them sorry, because they sorrowed to repentance after a godly manner." }
    ] },
  { n:8, summary:"Paul reports the grace of God at work in the churches of Macedonia: in great affliction and deep poverty, their joy overflowed into rich generosity, giving beyond their ability and begging for a share in relieving the needy saints, because they first gave themselves to the Lord. He asks Titus to complete this same grace among the Corinthians, who already abound in faith, speech, knowledge, and love; the appeal is not a command but a test of sincere love. The measure is Christ Himself: though He was rich, He became poor so that through His poverty they might be rich. They began the collection a year ago, so now they should finish it; God accepts a willing mind according to what a person has, not what he lacks, and the goal is equality, the abundance of one supplying the want of another. Trusted brothers will carry the gift, so that it is handled honourably before God and men.",
    context:"Paul lifts up Macedonia's generous giving to spur the Corinthians to complete their collection for the poor saints.",
    keyVerses:[
      { ref:"2 Corinthians 8:5", text:"And this they did, not as we hoped, but first gave their own selves to the Lord, and unto us by the will of God." },
      { ref:"2 Corinthians 8:9", text:"For ye know the grace of our Lord Jesus Christ, that, though he was rich, yet for your sakes he became poor, that ye through his poverty might be rich." },
      { ref:"2 Corinthians 8:12", text:"For if there be first a willing mind, it is accepted according to that a man hath, and not according to that he hath not." }
    ],
    takeaway:"Give yourselves first to the Lord; a willing mind, not the amount, makes the gift acceptable.",
    quiz:[
      { q:"Whose churches does Paul hold up as examples of generous giving?", choices:["Jerusalem's","Corinth's","Rome's","Macedonia's"], a:3, why:"Verses 1-2 tell of the grace of God bestowed on the churches of Macedonia, whose deep poverty abounded to rich liberality." },
      { q:"How does Paul ground the call to give in Christ Himself?", choices:["Christ commanded a yearly tax","Christ refused all wealth","Though He was rich, He became poor so that through His poverty believers might be rich","Christ only helped those who gave"], a:2, why:"Verse 9 points to the grace of our Lord Jesus Christ, who for their sakes became poor that they might be rich." },
      { q:"What makes a gift acceptable to God, according to verse 12?", choices:["Its size","A willing mind, accepted according to what a man has","The giver's reputation","Public recognition"], a:1, why:"Verse 12 says if there be first a willing mind, it is accepted according to that a man hath, and not according to that he hath not." }
    ] },
  { n:9, summary:"Paul continues the practical matter of the collection. He has boasted to the Macedonians that Achaia was ready a year ago, so he sends brethren ahead to prepare the bounty, lest his boasting prove empty. Then the principle: he who sows sparingly shall reap sparingly, and he who sows bountifully shall reap bountifully. Let every man give as he purposes in his heart, not grudgingly or by necessity, for God loves a cheerful giver, and God is able to make all grace abound so that, having sufficiency in all things, they may abound to every good work. Righteous giving spreads supplies to the poor saints, multiplies thanksgiving to God, and draws prayers and deep affection from those who receive it. The chapter ends in praise: thanks be unto God for His unspeakable gift.",
    context:"Paul teaches the blessings of willing, cheerful giving in the collection for the saints at Jerusalem.",
    keyVerses:[
      { ref:"2 Corinthians 9:6", text:"But this I say, He which soweth sparingly shall reap also sparingly; and he which soweth bountifully shall reap also bountifully." },
      { ref:"2 Corinthians 9:7", text:"Every man according as he purposeth in his heart, so let him give; not grudgingly, or of necessity: for God loveth a cheerful giver." },
      { ref:"2 Corinthians 9:15", text:"Thanks be unto God for his unspeakable gift." }
    ],
    takeaway:"God loves a cheerful giver, and generous sowing reaps a harvest of thanksgiving and righteousness.",
    quiz:[
      { q:"What kind of giver does Paul say God loves?", choices:["A cheerful giver","A silent giver","A famous giver","A wealthy giver"], a:0, why:"Verse 7 says every man should give as he purposeth in his heart, not grudgingly or of necessity: for God loveth a cheerful giver." },
      { q:"How does Paul use farming to teach about giving?", choices:["Fields must rest every seventh year","He who sows sparingly reaps sparingly, and he who sows bountifully reaps bountifully","Only wheat counts as a valid offering","Harvests depend on the weather"], a:1, why:"Verse 6 draws the sowing-and-reaping parallel: he which soweth sparingly shall reap also sparingly, and he which soweth bountifully shall reap also bountifully." },
      { q:"How does Paul say giving should be decided in the heart?", choices:["By necessity alone","By comparison with the Macedonians","As each man purposeth in his heart, not grudgingly or of necessity","By the amount the church assigns"], a:2, why:"Verse 7 says every man according as he purposeth in his heart, so let him give; not grudgingly, or of necessity." }
    ] },
  { n:10, summary:"Paul answers critics who say his letters are weighty but his bodily presence weak and his speech contemptible. He pleads by the meekness and gentleness of Christ: though he lives in the world, he does not war the way the world does, for his weapons are not carnal but mighty through God to pull down strong holds, casting down imaginations and every high thing that exalts itself against the knowledge of God and taking every thought captive to the obedience of Christ. His authority exists for edification, not destruction. Self-commendation is folly: those who measure themselves by themselves are not wise. Paul boasts only within the sphere God assigned him, a work that reached all the way to Corinth, where he preached the gospel first, with hope to carry the gospel to regions beyond. The rule stands: he that glories must glory in the Lord, for the Lord's commendation, not self-praise, counts.",
    context:"Paul opens his direct defense against critics who measure him by outward appearance and dismiss his personal presence.",
    keyVerses:[
      { ref:"2 Corinthians 10:4", text:"(For the weapons of our warfare are not carnal, but mighty through God to the pulling down of strong holds;)" },
      { ref:"2 Corinthians 10:5", text:"Casting down imaginations, and every high thing that exalteth itself against the knowledge of God, and bringing into captivity every thought to the obedience of Christ;" },
      { ref:"2 Corinthians 10:17", text:"But he that glorieth, let him glory in the Lord." }
    ],
    takeaway:"Spiritual battles are won by God's power, and approval comes from the Lord, not self-praise.",
    quiz:[
      { q:"What did Paul's critics say about him?", choices:["He charged fees for preaching","He was not a real Jew","His letters are weighty, but his bodily presence is weak and his speech contemptible","He wrote in a foreign language"], a:2, why:"Verse 10 quotes them: his letters are weighty and powerful; but his bodily presence is weak, and his speech contemptible." },
      { q:"What makes Paul's weapons effective in spiritual warfare?", choices:["They are mighty through God to pull down strong holds","They are carefully sharpened","They rely on majority support","They are hidden from opponents"], a:0, why:"Verses 4-5 say the weapons of our warfare are not carnal but mighty through God, casting down imaginations and taking every thought captive to the obedience of Christ." },
      { q:"Whom does Paul say is approved?", choices:["Whoever has the largest following","Whom the Lord commendeth, not he that commendeth himself","Whoever wins public debates","Whoever writes the strongest letters"], a:1, why:"Verse 18 says not he that commendeth himself is approved, but whom the Lord commendeth." }
    ] },
  { n:11, summary:"Paul begs them to bear with a little foolish boasting: betrothed to one husband, Christ, they should remain a chaste virgin. He fears the serpent's old trick, that their minds will be corrupted from the simplicity in Christ until they tolerate another Jesus, another spirit, or another gospel. He preached freely and refused to be a burden, cutting off ground from false apostles, deceitful workers who disguise themselves as apostles of Christ — no marvel, since Satan himself is transformed into an angel of light. Then the reluctant ledger: Hebrew, Israelite, seed of Abraham — so is he; minister of Christ — more: labours beyond measure, stripes above measure, prisons frequent, deaths often, five times the Jews' forty lashes save one, three beatings with rods, a stoning, three shipwrecks, a night and a day in the deep, perils of every kind, hunger and cold — and beside all that, the daily care of all the churches. If he must glory, he will glory in his infirmities.",
    context:"Paul reluctantly boasts of his sufferings to expose the false apostles who had gained influence at Corinth.",
    keyVerses:[
      { ref:"2 Corinthians 11:3", text:"But I fear, lest by any means, as the serpent beguiled Eve through his subtilty, so your minds should be corrupted from the simplicity that is in Christ." },
      { ref:"2 Corinthians 11:14", text:"And no marvel; for Satan himself is transformed into an angel of light." },
      { ref:"2 Corinthians 11:24", text:"Of the Jews five times received I forty stripes save one." }
    ],
    takeaway:"True servants of Christ are marked by sacrifice and suffering, not impressive credentials.",
    quiz:[
      { q:"How many times did Paul say he received of the Jews forty stripes save one?", choices:["Two","Three","Four","Five"], a:3, why:"Verse 24 says of the Jews five times received I forty stripes save one." },
      { q:"Why is it no marvel that false apostles disguise themselves?", choices:["Everyone does this","Because Satan himself is transformed into an angel of light","They are only entertainers","They confess it openly"], a:1, why:"Verses 13-15 describe false apostles transforming themselves into apostles of Christ, no marvel since Satan himself is transformed into an angel of light." },
      { q:"What did Paul choose to boast in?", choices:["The things which concern his infirmities","His rhetorical training","His Roman citizenship","The churches he founded"], a:0, why:"Verse 30 says if I must needs glory, I will glory of the things which concern mine infirmities." }
    ] },
  { n:12, summary:"Paul turns, unwillingly, to visions. Fourteen years earlier a man in Christ, whom Paul describes in the third person, was caught up to the third heaven, into paradise, where he heard unspeakable words not lawful for a man to utter. Of such an experience he will not boast, but in his infirmities, lest anyone credit him above what they see and hear. Lest the abundance of revelations lift him up, a thorn in the flesh, the messenger of Satan, was given to buffet him. Three times he begged the Lord to take it away; the answer became a testimony of grace: My grace is sufficient for thee, for my strength is made perfect in weakness. So Paul takes pleasure in weaknesses, reproaches, necessities, and persecutions — when he is weak, then he is strong. He points to the signs of an apostle already done among them, to his refusal of their money, and to his fear of finding strife and unrepented sin when he comes.",
    context:"Paul recounts visions, the thorn in the flesh, and the sufficiency of grace, then warns of coming discipline.",
    keyVerses:[
      { ref:"2 Corinthians 12:7", text:"And lest I should be exalted above measure through the abundance of the revelations, there was given to me a thorn in the flesh, the messenger of Satan to buffet me, lest I should be exalted above measure." },
      { ref:"2 Corinthians 12:9", text:"And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me." },
      { ref:"2 Corinthians 12:10", text:"Therefore I take pleasure in infirmities, in reproaches, in necessities, in persecutions, in distresses for Christ's sake: for when I am weak, then am I strong." }
    ],
    takeaway:"God's grace is sufficient: His strength is made perfect in our weakness.",
    quiz:[
      { q:"How many times did Paul beseech the Lord to remove the thorn in the flesh?", choices:["Once","Three times","Seven times","Twelve times"], a:1, why:"Verse 8 says for this thing I besought the Lord thrice, that it might depart from me." },
      { q:"Why was the thorn in the flesh given to Paul?", choices:["As punishment for persecution","To stop his travels","Lest he be exalted above measure through the abundance of the revelations","Because of an illness in Damascus"], a:2, why:"Verse 7 explains the thorn kept Paul from being exalted above measure through the abundance of the revelations." },
      { q:"What did the Lord answer when Paul pleaded for relief?", choices:["The thorn would vanish at once","He should see a physician","It was only imagination","My grace is sufficient for thee: for my strength is made perfect in weakness"], a:3, why:"Verse 9 gives the answer, and Paul responds that most gladly will he glory in infirmities, that the power of Christ may rest upon him." }
    ] },
  { n:13, summary:"Paul warns that his third visit will carry authority: at the mouth of two or three witnesses every word is established, and he will not spare those who persisted in sin. The proof they seek of Christ speaking in him stands already: Christ was crucified through weakness yet lives by the power of God, and believers share that power. The great command is inward: examine yourselves, whether you are in the faith; prove your own selves, and recognize that Jesus Christ is in you. Paul can do nothing against the truth, only for it; he is glad to be weak if they are strong, and he wishes their perfection. He writes while absent so that he will not have to use sharpness when present, for the Lord gave him power for edification, not destruction. The letter closes on peace: be perfect, be of good comfort, be of one mind, live in peace, and the God of love and peace shall be with you.",
    context:"Paul warns of a third visit with apostolic authority and calls the Corinthians to examine themselves.",
    keyVerses:[
      { ref:"2 Corinthians 13:5", text:"Examine yourselves, whether ye be in the faith; prove your own selves. Know ye not your own selves, how that Jesus Christ is in you, except ye be reprobates?" },
      { ref:"2 Corinthians 13:11", text:"Finally, brethren, farewell. Be perfect, be of good comfort, be of one mind, live in peace; and the God of love and peace shall be with you." },
      { ref:"2 Corinthians 13:14", text:"The grace of the Lord Jesus Christ, and the love of God, and the communion of the Holy Ghost, be with you all. Amen." }
    ],
    takeaway:"Examine yourself in the faith, and let all authority be used to build up, not destroy.",
    quiz:[
      { q:"How does Paul say every word shall be established?", choices:["In the mouth of two or three witnesses","By a signed affidavit","By a vote of the church","By a vision from an angel"], a:0, why:"Verse 1 cites the standard: in the mouth of two or three witnesses shall every word be established." },
      { q:"What does Paul command the Corinthians to do about themselves?", choices:["Judge the false apostles annually","Appoint new leaders","Send an offering to Jerusalem","Examine yourselves, whether ye be in the faith; prove your own selves"], a:3, why:"Verse 5 commands self-examination, asking whether they know that Jesus Christ is in them." },
      { q:"For what purpose did Paul say the Lord gave him power?", choices:["To collect tribute","To punish opponents","To edification, and not to destruction","To found new colonies"], a:2, why:"Verse 10 says he writes to avoid sharpness, according to the power which the Lord hath given him to edification, and not to destruction." }
    ] });
var _gl = SLP.books.find(function(b){ return b.id === "gal"; });
if (!_gl) throw new Error("data/canon.js must load before nt-06-2cor-col.js");
(_gl.chapters = _gl.chapters || []).push(
  { n:1, summary:"Paul greets the churches of Galatia and moves immediately to the crisis: he marvels that they are so soon removed from Him who called them into the grace of Christ toward another gospel, which is not really another but a perversion by those troubling the churches. Anyone, even an angel from heaven, who preaches a different gospel is to be accursed; and Paul does not seek to please men, for then he would not be Christ's servant. Next he establishes the source of his message: the gospel he preached came neither from man nor by instruction, but by the revelation of Jesus Christ. His past proves the point, for he had persecuted the church beyond measure and advanced in Judaism above his peers. But God, who separated him from the womb, revealed His Son in him; he consulted no one, went to Jerusalem only three years later to see Peter for fifteen days, and remained unknown by face to the churches of Judaea, which glorified God in him.",
    context:"Paul writes to the churches of Galatia, likely Gentile converts, after teachers arrived insisting that Gentile believers must be circumcised and keep the law of Moses.",
    keyVerses:[
      { ref:"Galatians 1:6", text:"I marvel that ye are so soon removed from him that called you into the grace of Christ unto another gospel:" },
      { ref:"Galatians 1:12", text:"For I neither received it of man, neither was I taught it, but by the revelation of Jesus Christ." },
      { ref:"Galatians 1:23", text:"But they had heard only, That he which persecuted us in times past now preacheth the faith which once he destroyed." }
    ],
    takeaway:"The true gospel comes by revelation from Christ, and no one may alter it to please men.",
    quiz:[
      { q:"How long after his conversion did Paul go up to Jerusalem, according to Galatians 1?", choices:["Forty days","One year","Three years","Fourteen years"], a:2, why:"Verse 18 says after three years Paul went up to Jerusalem to see Peter and abode with him fifteen days." },
      { q:"What does Paul say is the source of the gospel he preached?", choices:["The elders in Jerusalem","Neither received of man nor taught, but by the revelation of Jesus Christ","His training under his fathers' traditions","A compromise between Peter and Barnabas"], a:1, why:"Verse 12 says he neither received it of man, neither was he taught it, but by the revelation of Jesus Christ." },
      { q:"Why does Paul say he cannot preach a gospel shaped by popular approval?", choices:["If he yet pleased men, he should not be the servant of Christ","Men would not understand it","Popular approval is expensive","Angels forbid it"], a:0, why:"Verse 10 says if I yet pleased men, I should not be the servant of Christ; even an angel from heaven preaching another gospel is accursed." }
    ] },
  { n:2, summary:"Fourteen years later Paul went to Jerusalem by revelation with Barnabas and Titus, and laid his Gentile gospel before the leaders privately, lest his work prove in vain. Titus, though a Greek, was not compelled to be circumcised; false brethren who slipped in to spy out their liberty in Christ were given place not even for an hour, so the truth of the gospel might continue. The pillars — James, Cephas, and John — gave Paul and Barnabas the right hands of fellowship, sending him to the Gentiles while they went to the circumcision, asking only that the poor be remembered. Then the confrontation at Antioch: Peter, who had eaten with Gentiles, withdrew when certain men came from James, fearing the circumcision party, and even Barnabas dissembled with him. Paul withstood him to the face: a man is not justified by the works of the law but by the faith of Jesus Christ. I am crucified with Christ, Paul says; Christ lives in me, and if righteousness came by the law, Christ died in vain.",
    context:"Paul recounts how the leaders in Jerusalem affirmed his Gentile gospel, and how he rebuked Peter at Antioch for withdrawing from Gentile meals.",
    keyVerses:[
      { ref:"Galatians 2:16", text:"Knowing that a man is not justified by the works of the law, but by the faith of Jesus Christ, even we have believed in Jesus Christ, that we might be justified by the faith of Christ, and not by the works of the law: for by the works of the law shall no flesh be justified." },
      { ref:"Galatians 2:20", text:"I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me." },
      { ref:"Galatians 2:21", text:"I do not frustrate the grace of God: for if righteousness come by the law, then Christ is dead in vain." }
    ],
    takeaway:"We are justified by faith in Christ, not by the works of the law; Christ lives in those He redeemed.",
    quiz:[
      { q:"Whom did Paul withstand to the face at Antioch?", choices:["Barnabas","James","Titus","Peter"], a:3, why:"Verse 11 says when Peter was come to Antioch, I withstood him to the face, because he was to be blamed." },
      { q:"What charge did Paul level at Peter's withdrawal from Gentile meals?", choices:["He compelled Gentiles to live as do the Jews, walking not uprightly according to the truth of the gospel","He was eating forbidden foods","He neglected prayer","He gathered crowds too large"], a:0, why:"Verses 12-14 describe Peter's fear of the circumcision party and Paul's rebuke that he compelled the Gentiles to live as do the Jews." },
      { q:"What does Paul mean by I am crucified with Christ: nevertheless I live?", choices:["He gave up preaching","He considered himself dead to Rome","His life is now lived by the faith of the Son of God, Christ living in him","He had legally died and returned"], a:2, why:"Verse 20 says yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God." }
    ] },
  { n:3, summary:"Did you receive the Spirit by the works of the law or by the hearing of faith? Scripture settles it: Abraham believed God, and it was counted to him for righteousness, so those of faith are blessed with faithful Abraham. The other road is hopeless, for as many as are of the works of the law are under its curse; but Christ redeemed us from that curse, being made a curse for us, hanged on a tree, so that the blessing of Abraham and the promise of the Spirit come to the Gentiles through faith. The law, coming centuries after the confirmed promise, cannot annul it; it was added because of transgressions till the seed, Christ, came — a schoolmaster to bring us to Him. Now that faith is come, believers are God's children: baptized into Christ, they have put on Christ, where there is neither Jew nor Greek, bond nor free, male nor female — all one in Christ Jesus, and heirs according to the promise.",
    context:"Paul argues from experience, from Abraham, and from the law's timing that blessing and the Spirit come by faith, not law-keeping.",
    keyVerses:[
      { ref:"Galatians 3:24", text:"Wherefore the law was our schoolmaster to bring us unto Christ, that we might be justified by faith." },
      { ref:"Galatians 3:26", text:"For ye are all the children of God by faith in Christ Jesus." },
      { ref:"Galatians 3:28", text:"There is neither Jew nor Greek, there is neither bond nor free, there is neither male nor female: for ye are all one in Christ Jesus." }
    ],
    takeaway:"The law was a schoolmaster to bring us to Christ; by faith believers are Abraham's children and heirs.",
    quiz:[
      { q:"What does Paul call the law in his analogy about coming to Christ?", choices:["A fortress","A schoolmaster","A mirror","A bridge"], a:1, why:"Verse 24 says the law was our schoolmaster to bring us unto Christ, that we might be justified by faith." },
      { q:"How does Paul prove that Abraham's blessing comes by faith?", choices:["By listing Moses' miracles","By quoting the elders in Jerusalem","By a census of believers","Abraham believed God, and it was accounted to him for righteousness"], a:3, why:"Verse 6 quotes Abraham believed God, and it was accounted to him for righteousness; so they which are of faith are blessed with faithful Abraham." },
      { q:"What social barriers does Galatians 3 say are dissolved for those in Christ?", choices:["Only the barrier between rich and poor","Only the barrier between slave and free","Jew and Greek, bond and free, male and female — all one in Christ Jesus","None; barriers remain forever"], a:2, why:"Verse 28 declares there is neither Jew nor Greek, bond nor free, male nor female: for ye are all one in Christ Jesus." }
    ] },
  { n:4, summary:"An heir who is a child differs nothing from a servant until the father's appointed time; so we, in childhood, were in bondage to the world's elements. But when the fulness of time came, God sent forth His Son, made of a woman, made under the law, to redeem those under the law and grant the adoption of sons; because they are sons, God sent the Spirit of His Son into their hearts, crying, Abba, Father — no longer servants but sons, and if sons, heirs of God through Christ. Paul grieves that, knowing God, they turn back to observing days, months, times, and years. He recalls how they received him in bodily weakness as an angel of God, and asks if telling the truth has made him their enemy, travailing until Christ be formed in them. Finally the allegory: Abraham's two sons, one by the bondmaid and one by the freewoman, stand for two covenants — Sinai, which genders to bondage, and the Jerusalem above, which is free.",
    context:"Paul pictures the law as childhood tutoring that ends when God's Son comes, then uses Abraham's bondmaid and freewoman to contrast two covenants.",
    keyVerses:[
      { ref:"Galatians 4:4", text:"But when the fulness of the time was come, God sent forth his Son, made of a woman, made under the law," },
      { ref:"Galatians 4:6", text:"And because ye are sons, God hath sent forth the Spirit of his Son into your hearts, crying, Abba, Father." },
      { ref:"Galatians 4:7", text:"Wherefore thou art no more a servant, but a son; and if a son, then an heir of God through Christ." }
    ],
    takeaway:"God sent His Son at the fulness of time to adopt us as sons and heirs, not servants.",
    quiz:[
      { q:"What word does the Spirit of God's Son cry in believers' hearts?", choices:["Abba, Father","Hosanna","Maranatha","Selah"], a:0, why:"Verse 6 says God hath sent forth the Spirit of his Son into your hearts, crying, Abba, Father." },
      { q:"In Paul's allegory, what do Abraham's two sons represent?", choices:["Two rival churches in Galatia","Paul and Peter","Two covenants — Sinai's bondage and the freedom of the Jerusalem above","Angels and men"], a:2, why:"Verse 24 says these are the two covenants, the one from mount Sinai gendering to bondage; verse 26 names the Jerusalem above, which is free." },
      { q:"What does it mean to be a son and heir rather than a servant?", choices:["Servants have more duties","Heirs earn their inheritance","Only Jewish believers are heirs","Through Christ believers receive the adoption, and if a son, then an heir of God"], a:3, why:"Verses 5 and 7 teach that God sent His Son to redeem those under the law so we might receive the adoption of sons, making us heirs of God through Christ." }
    ] },
  { n:5, summary:"Stand fast in the liberty wherewith Christ made us free, Paul charges, and be not entangled again with the yoke of bondage: whoever accepts circumcision as required becomes a debtor to the whole law and falls from grace. What avails is neither circumcision nor uncircumcision, but faith which works by love. A little leaven leavens the whole lump, and the one troubling them will bear his judgment. Liberty is not license: do not use freedom as an occasion for the flesh, but by love serve one another, for all the law is fulfilled in one word — love thy neighbour as thyself. The way to defeat the flesh is to walk in the Spirit, whose desires war against the flesh's. The works of the flesh are listed, including adultery, idolatry, hatred, variance, wrath, strife, envyings, and drunkenness, and those who do such things shall not inherit the kingdom of God. But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith, meekness, temperance: against such there is no law.",
    context:"Paul contrasts liberty in the Spirit with bondage to the law and with slavery to the flesh, listing the fruit of the Spirit.",
    keyVerses:[
      { ref:"Galatians 5:1", text:"Stand fast therefore in the liberty wherewith Christ hath made us free, and be not entangled again with the yoke of bondage." },
      { ref:"Galatians 5:13", text:"For, brethren, ye have been called unto liberty; only use not liberty for an occasion to the flesh, but by love serve one another." },
      { ref:"Galatians 5:22", text:"But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith," }
    ],
    takeaway:"Christ set us free: walk in the Spirit, serve in love, and bear the Spirit's fruit.",
    quiz:[
      { q:"Which of the following is named among the fruit of the Spirit?", choices:["Wrath","Envyings","Revellings","Longsuffering"], a:3, why:"Verse 22 lists love, joy, peace, longsuffering, gentleness, goodness, faith, meekness, and temperance; wrath, envyings, and revellings appear among the works of the flesh." },
      { q:"What does Paul say about Christian liberty?", choices:["Liberty means there are no moral expectations","Use not liberty for an occasion to the flesh, but by love serve one another","Liberty ends at baptism","Liberty applies only to food laws"], a:1, why:"Verse 13 says ye have been called unto liberty; only use not liberty for an occasion to the flesh, but by love serve one another." },
      { q:"According to Galatians 5, how does a believer avoid fulfilling the lust of the flesh?", choices:["By walking in the Spirit","By keeping a strict calendar","By isolation from society","By repeating the law daily"], a:0, why:"Verse 16 says walk in the Spirit, and ye shall not fulfil the lust of the flesh, for the Spirit and the flesh are contrary the one to the other." }
    ] },
  { n:6, summary:"Paul turns to practical life. A brother overtaken in a fault should be restored by those who are spiritual, in a spirit of meekness, each watching himself lest he also be tempted. Bear one another's burdens and so fulfil the law of Christ, yet each must also prove his own work, and every man shall bear his own load; those taught in the word should share all good things with their teacher. The harvest law is certain: God is not mocked — whatsoever a man soweth, that shall he also reap; sowing to the flesh reaps corruption, sowing to the Spirit reaps life everlasting. Let us not be weary in well doing, for in due season we shall reap if we faint not, doing good to all men, especially the household of faith. Against those pushing circumcision to avoid persecution, Paul glories only in the cross of our Lord Jesus Christ, insists that a new creature is what counts, and points to the marks of the Lord Jesus in his own body.",
    context:"Paul closes with practical charges about restoring others, sowing to the Spirit, and boasting only in the cross.",
    keyVerses:[
      { ref:"Galatians 6:2", text:"Bear ye one another's burdens, and so fulfil the law of Christ." },
      { ref:"Galatians 6:7", text:"Be not deceived; God is not mocked: for whatsoever a man soweth, that shall he also reap." },
      { ref:"Galatians 6:14", text:"But God forbid that I should glory, save in the cross of our Lord Jesus Christ, by whom the world is crucified unto me, and I unto the world." }
    ],
    takeaway:"Sow to the Spirit, bear one another's burdens, and glory only in the cross of Christ.",
    quiz:[
      { q:"What does Paul note about the physical writing of this letter?", choices:["It was written on stone","It was dictated to Titus","I have written unto you with mine own hand in large letters","It was lost and recopied"], a:2, why:"Verse 11 says ye see how large a letter I have written unto you with mine own hand." },
      { q:"What does Galatians 6 teach about what a person will reap?", choices:["Whatsoever a man soweth, that shall he also reap","Everyone reaps the same harvest","Sowing to the Spirit reaps nothing now","Reaping is postponed to the next life only"], a:0, why:"Verse 7 warns God is not mocked: he that soweth to his flesh shall of the flesh reap corruption; he that soweth to the Spirit shall of the Spirit reap life everlasting." },
      { q:"How should the spiritual respond to a brother overtaken in a fault?", choices:["Publicly shame him","Restore him in the spirit of meekness, considering yourself lest you also be tempted","Wait for him to apologize first","Report him to the authorities"], a:1, why:"Verse 1 instructs the spiritual to restore such a one in the spirit of meekness, considering thyself, lest thou also be tempted." }
    ] });
var _ep = SLP.books.find(function(b){ return b.id === "eph"; });
if (!_ep) throw new Error("data/canon.js must load before nt-06-2cor-col.js");
(_ep.chapters = _ep.chapters || []).push(
  { n:1, summary:"Paul opens with a doxology: God has blessed us with all spiritual blessings in heavenly places, choosing us in Christ before the foundation of the world to be holy and without blame, adopting us as children and making us accepted in the Beloved, in whom we have redemption through His blood, the forgiveness of sins. The mystery of His will is to gather together in one all things in Christ in the fulness of times; believers have obtained an inheritance and were sealed with the holy Spirit of promise, the earnest of it. Paul prays that the eyes of their understanding be enlightened to know the hope of His calling, the riches of His inheritance, and the exceeding greatness of His power — the power that raised Christ and set Him far above all principality, making Him head over all things to the church, which is His body, the fulness of Him that filleth all in all.",
    context:"Paul, traditionally writing while under Roman guard, sends this letter to the saints at Ephesus celebrating God's plan to unite everything in Christ.",
    keyVerses:[
      { ref:"Ephesians 1:10", text:"That in the dispensation of the fulness of times he might gather together in one all things in Christ, both which are in heaven, and which are on earth; even in him:" },
      { ref:"Ephesians 1:13", text:"In whom ye also trusted, after that ye heard the word of truth, the gospel of your salvation: in whom also after that ye believed, ye were sealed with that holy Spirit of promise," },
      { ref:"Ephesians 1:23", text:"Which is his body, the fulness of him that filleth all in all." }
    ],
    takeaway:"God's eternal plan gathers all things in Christ, and believers are sealed for that inheritance by His Spirit.",
    quiz:[
      { q:"With what were the Ephesian believers sealed after they believed?", choices:["Circumcision","That holy Spirit of promise","Baptismal oil","A wax seal on their letters"], a:1, why:"Verse 13 says after that ye believed, ye were sealed with that holy Spirit of promise, called the earnest of the inheritance in verse 14." },
      { q:"What is God's plan for the fulness of times?", choices:["To scatter Israel among the nations","To rebuild the Jerusalem temple","To delay all judgment","To gather together in one all things in Christ"], a:3, why:"Verse 10 describes the dispensation of the fulness of times, when God will gather together in one all things in Christ, both in heaven and on earth." },
      { q:"What does it mean that the church is Christ's body?", choices:["Christ governs through the emperor","The church is merely symbolic","Christ is head over all things to the church, His fulness that fills all in all","Believers replace the Old Testament"], a:2, why:"Verses 22-23 say God gave Christ to be the head over all things to the church, which is his body, the fulness of him that filleth all in all." }
    ] },
  { n:2, summary:"Once they were dead in trespasses and sins, walking by the course of this world and its prince, the power of the air; but God, rich in mercy and great in love, quickened us together with Christ and seated us in heavenly places. Salvation is by grace through faith, the gift of God, not of works, lest any man should boast; we are His workmanship, created in Christ Jesus unto good works. Then the Gentile story: once without Christ, aliens from Israel's commonwealth, strangers from the covenants of promise, having no hope and without God — but now made nigh by the blood of Christ, who is our peace, breaking down the middle wall of partition and abolishing the enmity's ordinances, making of two one new man, reconciling both to God in one body by the cross. Therefore they are no more strangers but fellowcitizens with the saints and of the household of God, built on the apostles' and prophets' foundation, Jesus Christ the chief corner stone, growing into a holy temple for God through the Spirit.",
    context:"Paul moves from salvation by grace to the uniting of Jew and Gentile into one new man and God's household.",
    keyVerses:[
      { ref:"Ephesians 2:8", text:"For by grace are ye saved through faith; and that not of yourselves: it is the gift of God:" },
      { ref:"Ephesians 2:14", text:"For he is our peace, who hath made both one, and hath broken down the middle wall of partition between us;" },
      { ref:"Ephesians 2:19", text:"Now therefore ye are no more strangers and foreigners, but fellowcitizens with the saints, and of the household of God;" }
    ],
    takeaway:"By grace we are saved, and Christ's blood breaks down every wall, making one household of God.",
    quiz:[
      { q:"What did Christ break down between Jew and Gentile?", choices:["The middle wall of partition","The veil of the temple","The gates of Damascus","The city walls of Ephesus"], a:0, why:"Verse 14 says he is our peace, who hath made both one, and hath broken down the middle wall of partition between us." },
      { q:"How were Gentiles who were once far off brought near?", choices:["By adopting Roman customs","By receiving circumcision","By the blood of Christ","By keeping the feasts"], a:2, why:"Verse 13 says now in Christ Jesus ye who sometimes were far off are made nigh by the blood of Christ." },
      { q:"Why does Paul say salvation is not of works?", choices:["Because works are worthless in daily life","Lest any man should boast","Because the law was misunderstood","Because effort is impossible"], a:1, why:"Verses 8-9 say by grace are ye saved through faith, not of works, lest any man should boast; we are His workmanship, created in Christ Jesus unto good works." }
    ] },
  { n:3, summary:"Paul explains his ministry as steward of a mystery: a prisoner for the Gentiles, he received grace to make known what other ages had not been revealed — that Gentiles should be fellowheirs, of the same body, and partakers of the promise in Christ by the gospel. To him, less than the least of all saints, this grace was given, to preach the unsearchable riches of Christ and show the fellowship of the mystery hidden from the beginning in God, so that now the principalities and powers in heavenly places learn, through the church, the manifold wisdom of God according to the eternal purpose in Christ. He asks them not to faint at his tribulations, then prays that they be strengthened with might by His Spirit in the inner man, that Christ may dwell in their hearts by faith, rooted and grounded in love, able to comprehend the breadth, length, depth, and height, and to know the love of Christ which passes knowledge, filled with all the fulness of God.",
    context:"Paul explains the mystery of Gentiles as fellowheirs and prays for inner strength to grasp the love of Christ.",
    keyVerses:[
      { ref:"Ephesians 3:6", text:"That the Gentiles should be fellowheirs, and of the same body, and partakers of his promise in Christ by the gospel:" },
      { ref:"Ephesians 3:17", text:"That Christ may dwell in your hearts by faith; that ye, being rooted and grounded in love," },
      { ref:"Ephesians 3:19", text:"And to know the love of Christ, which passeth knowledge, that ye might be filled with all the fulness of God." }
    ],
    takeaway:"The mystery now revealed is one body of Jew and Gentile, and Christ's love surpasses all knowledge.",
    quiz:[
      { q:"What does Paul call himself in Ephesians 3?", choices:["The bishop of Ephesus","A deacon of the poor","The first witness of the resurrection","The prisoner of Jesus Christ for you Gentiles"], a:3, why:"Verse 1 opens, For this cause I Paul, the prisoner of Jesus Christ for you Gentiles." },
      { q:"What is the mystery now revealed in Ephesians 3?", choices:["That Gentiles should be fellowheirs, of the same body, and partakers of the promise in Christ by the gospel","The date of the second coming","The names of the fallen angels","A secret calendar of feasts"], a:0, why:"Verse 6 defines the mystery: that the Gentiles should be fellowheirs, of the same body, and partakers of his promise in Christ by the gospel." },
      { q:"What does Paul pray believers will know that passes knowledge?", choices:["The date of Christ's return","The love of Christ","The number of the angels","The length of Israel's exile"], a:1, why:"Verse 19 prays they may know the love of Christ, which passeth knowledge, that they might be filled with all the fulness of God." }
    ] },
  { n:4, summary:"Paul turns to daily walk: as a prisoner of the Lord he begs them to walk worthy of their calling, in lowliness, meekness, and longsuffering, forbearing one another in love and keeping the unity of the Spirit in the bond of peace — for there is one body and one Spirit, one hope, one Lord, one faith, one baptism, and one God and Father of all. The ascended Christ gave apostles, prophets, evangelists, pastors and teachers for the perfecting of the saints and the edifying of the body of Christ, till the church reaches the unity of the faith, no longer tossed by every wind of doctrine, but speaking the truth in love and growing up into Christ, from whom the whole body, fitly joined, makes increase of itself in love. The new life follows: put off the old man, be renewed in the spirit of the mind, and put on the new man — putting away lying, unrighteous anger, stealing, and corrupt speech; grieve not the Spirit; be kind, tenderhearted, forgiving one another, as God in Christ forgave you.",
    context:"Paul calls the church to unity, maturity, and the putting off of the old life in favor of the new man.",
    keyVerses:[
      { ref:"Ephesians 4:3", text:"Endeavouring to keep the unity of the Spirit in the bond of peace." },
      { ref:"Ephesians 4:11", text:"And he gave some, apostles; and some, prophets; and some, evangelists; and some, pastors and teachers;" },
      { ref:"Ephesians 4:32", text:"And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ's sake hath forgiven you." }
    ],
    takeaway:"One Lord, one faith, one baptism: unity grows as members speak truth in love and build up the body.",
    quiz:[
      { q:"According to Ephesians 4, how many ones unite believers in Christ?", choices:["Three","Five","Seven","Ten"], a:2, why:"Verses 4-6 list one body, one Spirit, one hope, one Lord, one faith, one baptism, and one God and Father of all." },
      { q:"Why does Christ give apostles, prophets, evangelists, pastors, and teachers?", choices:["To rule as kings","For the perfecting of the saints and the edifying of the body of Christ","To collect temple taxes","To keep records of the churches"], a:1, why:"Verse 12 gives the purpose: the perfecting of the saints, the work of the ministry, and the edifying of the body of Christ." },
      { q:"What standard does Paul set for forgiveness among believers?", choices:["Forgive twice at most","Forgive when the other apologizes first","Forgive only your family","Forgiving one another, even as God for Christ's sake hath forgiven you"], a:3, why:"Verse 32 commands kindness and forgiveness on the pattern of God's forgiveness in Christ." }
    ] },
  { n:5, summary:"Be followers of God as dear children, and walk in love, as Christ gave Himself for us an offering to God. Fornication, uncleanness, covetousness, filthiness, and foolish talking must not be named among saints; the covetous man, who is an idolater, has no inheritance in the kingdom, and no one should deceive them with vain words, for wrath comes on the disobedient. Once darkness, they are now light in the Lord: walk as children of light, having no fellowship with the unfruitful works of darkness but rather reproving them. Walk circumspectly, as wise, redeeming the time because the days are evil; be not drunk with wine but filled with the Spirit, singing psalms and hymns and spiritual songs, giving thanks always and submitting to one another. Then the household: wives submit to their husbands as to the Lord; husbands love their wives as Christ loved the church and gave Himself for it, to present it glorious, without spot or wrinkle — a great mystery concerning Christ and the church.",
    context:"Paul describes walking as children of light and the Spirit-filled life, then applies Christ's love to marriage.",
    keyVerses:[
      { ref:"Ephesians 5:2", text:"And walk in love, as Christ also hath loved us, and hath given himself for us an offering and a sacrifice to God for a sweetsmelling savour." },
      { ref:"Ephesians 5:8", text:"For ye were sometimes darkness, but now are ye light in the Lord: walk as children of light:" },
      { ref:"Ephesians 5:25", text:"Husbands, love your wives, even as Christ also loved the church, and gave himself for it;" }
    ],
    takeaway:"Walk as children of light, filled with the Spirit, letting Christ's sacrificial love shape every relationship.",
    quiz:[
      { q:"What does Paul say believers should be filled with instead of wine?", choices:["The Spirit","New doctrine","Zeal only","Oil"], a:0, why:"Verse 18 contrasts be not drunk with wine, wherein is excess, with be filled with the Spirit, singing and making melody in the heart." },
      { q:"What pattern does Paul give husbands for loving their wives?", choices:["As Rome honors its citizens","As fathers discipline children","As masters reward servants","As Christ also loved the church, and gave himself for it"], a:3, why:"Verse 25 commands husbands to love their wives as Christ loved the church and gave himself for it, to sanctify and cleanse it." },
      { q:"What does walking as children of light involve?", choices:["Avoiding all public life","Keeping light ceremonies","Having no fellowship with the unfruitful works of darkness, but rather reproving them","Only private worship"], a:2, why:"Verses 8-11 say ye were sometimes darkness, but now are ye light in the Lord: walk as children of light, reproving the works of darkness." }
    ] },
  { n:6, summary:"Paul finishes the household instructions: children obey their parents in the Lord, for honour thy father and mother is the first commandment with promise; fathers, provoke not your children to wrath but bring them up in the Lord's nurture and admonition. Servants serve as unto Christ, not with eyeservice as menpleasers, knowing whatsoever good any man does he shall receive of the Lord; masters, forbear threatening, remembering your Master in heaven respects no person. The climax: be strong in the Lord, putting on the whole armour of God to stand against the wiles of the devil, for we wrestle not against flesh and blood but against principalities and the rulers of the darkness of this world. The armour is truth, righteousness, the gospel of peace, the shield of faith, the helmet of salvation, the sword of the Spirit, which is the word of God — with prayer always in the Spirit for all saints, and for Paul, an ambassador in bonds, that he may speak boldly. Tychicus will carry the news, and grace closes the letter.",
    context:"Paul completes household duties and arms the believers for spiritual warfare with the whole armour of God.",
    keyVerses:[
      { ref:"Ephesians 6:11", text:"Put on the whole armour of God, that ye may be able to stand against the wiles of the devil." },
      { ref:"Ephesians 6:12", text:"For we wrestle not against flesh and blood, but against principalities, against powers, against the rulers of the darkness of this world, against spiritual wickedness in high places." },
      { ref:"Ephesians 6:17", text:"And take the helmet of salvation, and the sword of the Spirit, which is the word of God:" }
    ],
    takeaway:"Stand strong in the Lord, clothed in truth, righteousness, faith, salvation, the word of God, and prayer.",
    quiz:[
      { q:"Which piece of the armour of God is called the sword of the Spirit?", choices:["The shield of faith","The word of God","The helmet of salvation","The breastplate of righteousness"], a:1, why:"Verse 17 says take the helmet of salvation, and the sword of the Spirit, which is the word of God." },
      { q:"Why does Paul say the whole armour of God is needed?", choices:["Because we wrestle not against flesh and blood but against principalities and powers","Because Roman soldiers persecuted them","Because the church had armies","To defeat other believers in debate"], a:0, why:"Verse 12 explains the real struggle is against principalities, powers, and the rulers of the darkness of this world." },
      { q:"What attitude does Ephesians 6 require of servants toward their daily work?", choices:["Do only what is watched","Serve with resentment","Work only for wages","Doing the will of God from the heart, as unto the Lord and not to men"], a:3, why:"Verses 5-7 instruct singleness of heart, not eyeservice, with good will doing service as to the Lord, and not to men." }
    ] });
